const fullText = $json.output || $json.text || "";

// Pisahkan berdasarkan delimiter
const parts = fullText.split("###DATA###");

const textOnly = parts[0].trim();

let data = {};

if (parts.length > 1) {
  try {
    data = JSON.parse(parts[1].trim());
  } catch (e) {
    console.log("JSON parse error:", e);
    data = {};
  }
}

return [{
  json: {
    text: textOnly,
    category_id: data.category_id ?? null,
    name: data.name ?? null,
    level: data.level ?? null,
    room_id: data.room_id ?? $json.room_id ?? null
  }
}];
